using UnityEngine;

namespace SunsetState
{
    public sealed class StoryDefinition
    {
        public string Name,Contact,ChoiceA,ChoiceB,EndingA,EndingB;public string[] Chapters;
        public StoryDefinition(string name,string contact,string a,string b,string c,string choiceA,string choiceB,string endA,string endB)
        {Name=name;Contact=contact;Chapters=new[]{a,b,c};ChoiceA=choiceA;ChoiceB=choiceB;EndingA=endA;EndingB=endB;}
        string Text(int chapter)=>System.Array.IndexOf(StoryBook.Stories,this)==17?GovernorCampaign.Text(chapter):System.Array.IndexOf(StoryBook.Stories,this)==16?MafiaCampaign.Text(chapter):System.Array.IndexOf(StoryBook.Stories,this)==15?LawyerCampaign.Text(chapter):chapter>=20?LongStory.Text(System.Array.IndexOf(StoryBook.Stories,this),chapter-20):chapter<3?Chapters[chapter]:chapter<6?StoryExtensions.Chapters[System.Array.IndexOf(StoryBook.Stories,this)][chapter-3]:chapter<9?StoryFinalAct.Chapters[System.Array.IndexOf(StoryBook.Stories,this)][chapter-6]:StoryContinuation.Text(System.Array.IndexOf(StoryBook.Stories,this),chapter-9);
        public string Title(int chapter)=>Text(chapter).Split('|')[0];
        public string Brief(int chapter)=>Text(chapter).Split('|')[1];
    }
