    public sealed partial class GameRoot
    {
        public int[] StoryProgress=new int[18],StoryChoices=new int[18];
        int activeCampaignRole=-1,finishedStoryRole;bool storyTab=true;
        Mission MakeStoryMission(int role,int chapter,int choice)
        {
            int previousRole=RoleIndex;RoleIndex=role;Mission mission;
            if(OnVice)mission=MakeViceMission(role,chapter%10);
            else if(role==17)mission=MakeGovernorMission(chapter);
            else if(role==16)mission=MakeMafiaMission(chapter,choice);
            else if(role==15)mission=MakeLawyerMission(chapter,choice);
            else if(chapter>=20)mission=MakeLongStoryMission(role,chapter,choice);
            else if(chapter>=9)mission=MakeContinuationMission(role,chapter,choice);
            else if(role==13){mission=PrisonMission(chapter%3==2 && choice==1?0:1);mission.Release=chapter%3==2 && choice==0;}
            else mission=MakeMission(chapter%3);
            RoleIndex=previousRole;
            var story=StoryBook.Stories[role];mission.Title=story.Title(chapter);mission.Description=story.Brief(chapter);
            mission.Reward+=(chapter/3)*350+(role==2?400:0);
            if(!OnVice && chapter<9 && chapter%3==2 && role!=12 && role!=13)
            {
                mission.Points=new[]{choice==0?StateBuilder.SanFierro:StateBuilder.LasVenturas,WorldBuilder.Places[role].Position};
                mission.Steps=new[]{"Выполни встречу в "+(choice==0?"Сан-Фиерро":"Лас-Вентурасе"),"Вернись и заверши свою историю"};mission.Vehicle=true;mission.Reward+=choice==1?500:300;
            }
            return mission;
        }
        void BeginStory(int choice)
        {
            int chapter=StoryProgress[RoleIndex];if(chapter>=StoryBook.ChapterCount)return;
            int bit=chapter/3;
            if(chapter%3==1)StoryChoices[RoleIndex]=(StoryChoices[RoleIndex]&~(1<<bit))|((choice&1)<<bit);
            var mission=MakeStoryMission(RoleIndex,chapter,(StoryChoices[RoleIndex]>>bit)&1);
            ActivateMission(mission);activeCampaignRole=RoleIndex;Save();
        }
        void CompleteStoryChapter(int role)
        {
            StoryProgress[role]=Mathf.Clamp(StoryProgress[role]+1,0,StoryBook.ChapterCount);finishedStoryRole=role;Panel="story-finish";Time.timeScale=0;SetCursor(false);
        }
        bool DrawStoryJobs(float left,float h)
        {
            if(!storyTab)return false;
            var story=StoryBook.Stories[RoleIndex];int chapter=StoryProgress[RoleIndex];
            Label(left,85,950,45,"МОЯ ИСТОРИЯ / "+Roles[RoleIndex].Name.ToUpper(),heading);
            if(Button(new Rect(left+785,88,295,38),"ОБЫЧНЫЕ ПОДРАБОТКИ"))storyTab=false;
            GUI.color=Roles[RoleIndex].Color;Label(left,140,1060,85,story.Name,title);GUI.color=Color.white;
            Label(left,230,1050,35,story.Contact+"   /   Глав пройдено: "+chapter+" из "+StoryBook.ChapterCount+" · Этап "+(Mathf.Min(chapter,StoryBook.ChapterCount-1)/3+1),body);
            for(int i=0;i<3;i++){int index=Mathf.Min(chapter/3,(StoryBook.ChapterCount-1)/3)*3+i;if(index>=StoryBook.ChapterCount)continue;float x=left+i*360;RectBox(new Rect(x,285,345,55),new Color(.12f,.19f,.14f));GUI.color=index<chapter?Roles[0].Color:Color.white;Label(x+12,300,320,35,(index<chapter?"✓ ":(index+1)+". ")+story.Title(index),small);}GUI.color=Color.white;
            if(chapter>=StoryBook.ChapterCount)
            {
                Label(left,375,1030,140,(StoryChoices[RoleIndex]&StoryBook.FinalChoiceMask)==0?story.EndingA:story.EndingB,heading);
                Label(left,h-90,1050,45,"История завершена. Продолжай свободную игру, выполняй подработки или выбери другую роль через Tab.",small);return true;
            }
            RectBox(new Rect(left,365,1080,180),new Color(.1f,.16f,.12f));
            Label(left+20,381,1040,140,story.Brief(chapter),heading);
            Label(left,560,1050,32,"Цели выполняются у жёлтых маркеров с остановкой на 3 секунды. Новое задание заменит текущее.",small);
            if(chapter%3==1)
            {
                if(Button(new Rect(left,610,525,55),story.ChoiceA+" →"))BeginStory(0);
                if(Button(new Rect(left+550,610,530,55),story.ChoiceB+" →"))BeginStory(1);
            }
            else if(Button(new Rect(left,610,540,55),chapter==0?"НАЧАТЬ МОЮ ИСТОРИЮ →":"ПРОДОЛЖИТЬ ИСТОРИЮ →"))BeginStory(StoryChoices[RoleIndex]);
            return true;
        }
        void DrawStoryFinish(float left,float h)
        {
            var story=StoryBook.Stories[finishedStoryRole];int chapter=StoryProgress[finishedStoryRole];
            Label(left,110,1050,70,chapter==StoryBook.ChapterCount?"ТВОЯ ИСТОРИЯ ЗАВЕРШЕНА":chapter%3==0?"АКТ ЗАВЕРШЁН":"ГЛАВА ЗАВЕРШЕНА",title);
            GUI.color=Roles[finishedStoryRole].Color;Label(left,220,1000,40,story.Name+" / "+Roles[finishedStoryRole].Name,heading);GUI.color=Color.white;
            Label(left,295,1000,200,chapter==StoryBook.ChapterCount?((StoryChoices[finishedStoryRole]&StoryBook.FinalChoiceMask)==0?story.EndingA:story.EndingB):"Поручение выполнено. "+story.Contact+" выходит на связь.\n\nДалее: «"+story.Title(chapter)+"».\n"+story.Brief(chapter),heading);
            if(Button(new Rect(left,535,500,60),"ВЕРНУТЬСЯ В ГОРОД →")){Panel="";Time.timeScale=1;SetCursor(true);}
            Label(left,625,1050,40,"Прогресс каждой роли сохраняется отдельно. Tab — другая роль · J — сюжет и подработки.",small);
        }
    }
}
